double adaptive_trapezoidal(FunctionPtr f, double a, double b, double precision) {
    // Simple implementation of adaptive trapezoidal rule
    double old_result = (f->eval(a) + f->eval(b)) / 2.0;
    double h = std::abs(b - a) / 2.0;
    double result = old_result + f->eval((a + b) / 2.0);
    int N = 2;

    while ((4.0/3.0) * std::abs(result * h - old_result * h * 2) > precision) {
        old_result = result;
        N = N * 2;
        h = std::abs(b - a) / N;
        // Add new points
        for (int i = 0; (a + h + i * 2 * h) < b; ++i) {
            result += f->eval(a + h + 2 * h * i);
        }
    }

    return result * h;
}

