double adaptive_trapezoidal(FunctionPtr f, double a, double b, double precision) {
    // Implementation of adaptive trapezoidal rule
    double old_result = (f->eval(a) + f->eval(b)) / 2.0;
    double h = std::abs(b - a) / 2.0;
    double result = old_result + f->eval((a + b) / 2.0);
    int N = 2;

    // First approximation
    double approx = result * h * 2;

    while (true) {
        // Calculate next approximation with double the number of intervals
        double new_result = (f->eval(a) + f->eval(b)) / 2.0;
        double new_h = std::abs(b - a) / (N * 2);
        double sum = 0;
        for (int i = 0; i < N; i++) {
            new_result += f->eval(a + (i + 0.5) * (b - a) / N);
        }
        new_result = new_result / N;
        N *= 2;

        // Error estimation using Richardson extrapolation
        double error_est = (4.0/3.0) * std::abs(new_result * new_h - result * h);

        if (error_est <= precision) {
            return new_result * new_h; // Return the integral result
        }

        result = new_result;
        h = new_h;
        old_result = new_result;
    }

    return result * h;
}

