double adaptive_trapezoidal(FunctionPtr f, double a, double b, double precision) {
    // Initial step: basic trapezoidal rule with 1 panel
    double h = b - a;
    double T1 = (f->eval(a) + f->eval(b)) * h / 2.0;

    // Refine with more panels until precision is met
    int n = 1;
    double T2;

    do {
        // Double the number of panels
        n *= 2;
        h = (b - a) / n;

        // Calculate new approximation
        double sum = 0;
        for (int i = 0; i < n; i++) {
            sum += f->eval(a + i * h + h/2.0);  // Midpoint of each panel
        }

        T2 = (f->eval(a) + f->eval(b)) * h / 2.0 + sum * h;

        // Error estimation using Richardson extrapolation
        double error_est = std::abs(T2 - T1);

        if (error_est <= precision) {
            break;
        }

        T1 = T2;

    } while (std::abs(T2 - T1) > precision && n < 1000000); // Prevent infinite loop

    return T2;
